android {
    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
        }
    }
}

# Too broad: disables shrinking and obfuscation for the whole package
# -keep class com.example.** { *; }

# Narrow: only what reflection actually reads
-keepclassmembers class com.example.model.ApiError {
    <fields>;
}

// or on the class itself
@Keep
data class LegacyPayload(val id: String)
